import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"New Read Balancer in Ceph - Laura Flores, IBM","description":"","frontmatter":{"title":"New Read Balancer in Ceph - Laura Flores, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","读平衡器","性能优化","算法改进"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/New_Read_Balancer_in_Ceph_-_Laura_Flores_IBM.md","filePath":"posts/2023/New_Read_Balancer_in_Ceph_-_Laura_Flores_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2023/New_Read_Balancer_in_Ceph_-_Laura_Flores_IBM.md"};function p(s,e,_,n,i,d){return r(),t("div",null,[...e[0]||(e[0]=[o("<p>Ceph 新读平衡器介绍会议由 IBM 的 RADOS 工程师 Laura Flores 主讲，主要讨论了 Ceph 分布式存储系统中新引入的读平衡器，旨在优化存储性能和读取效率。</p><p><strong>会议要点</strong>：</p><ol><li><p><strong>读平衡的重要性</strong>：在分布式存储系统中，平衡读写请求对于优化性能至关重要。读平衡器专注于解决读取请求的不平衡问题，从而提高整体性能。</p></li><li><p><strong>现有平衡器的局限</strong>：现有的容量平衡器主要处理写入请求，不处理读取请求，导致读取性能受限。</p></li><li><p><strong>读平衡器的特点</strong>：适用于复制池，假设所有设备同质，操作成本低，仅涉及元数据操作，不涉及数据移动。</p></li><li><p><strong>新命令和工具</strong>：引入了新的 <code>ceph osd pool ls detail</code> 命令，显示读取平衡分数。新增 <code>ceph osd pg upmap primary</code> 命令，用于重新分配 PG 的主 OSD。</p></li><li><p><strong>未来计划和改进</strong>：计划将读平衡器集成到 Ceph 的测试套件中，作为默认平衡器模块的一部分。考虑将读平衡器扩展到异质系统。</p></li><li><p><strong>问答环节</strong>：讨论了读平衡器在不同版本 Ceph 中的适用性、与自动缩放器的潜在冲突，以及网络延迟对读取平衡的影响。</p></li></ol><p><strong>决定事项</strong>：</p><ul><li>鼓励社区成员尝试新读平衡器，并提供反馈。</li><li>计划将读平衡器集成到 Ceph 的默认平衡器模块中。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完善文档，详细说明新工具的使用方法和效果。</li><li>进行性能测试，验证读平衡器对集群性能的实际影响。</li><li>持续改进读平衡器，考虑设备异质性的处理。</li></ul>",7)])])}const u=a(l,[["render",p]]);export{g as __pageData,u as default};
